create table xxcus.xxcmp_ubo_determinations (
    ubo_id                number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    case_id               number not null enable,
    owner_party_id        number not null enable,
    basis                 varchar2(30 byte) not null enable,
    ownership_percentage  number,
    notes                 varchar2(4000 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_ubo_determinations
    add constraint xxcmp_ubo_determinations_ck1
        check ( basis in ( 'OWNERSHIP', 'CONTROL', 'FALLBACK' ) ) enable;

alter table xxcus.xxcmp_ubo_determinations
    add constraint xxcmp_ubo_determinations_ck2 check ( ownership_percentage between 0 and 100 ) enable;

alter table xxcus.xxcmp_ubo_determinations
    add constraint xxcmp_ubo_determinations_pk primary key ( ubo_id )
        using index enable;

alter table xxcus.xxcmp_ubo_determinations
    add constraint xxcmp_ubo_determinations_uk1 unique ( case_id,
                                                         owner_party_id )
        using index enable;


